const COMPANY = 'KQuality Cleaning Services';
const r = $json;
const n = Number(r.followup_count) + 1;
const name = String(r.business_name || '').replace(/\s+/g, ' ').trim();
const greeting = 'Hi ' + name + ' team,';
const signature = 'Kind regards,\n' + COMPANY;
let middle = '';
if (n === 1) {
  middle = 'Just floating our earlier note back to the top of your inbox - I know how busy things get.\n\nIf keeping your space consistently clean is something you would like taken off your plate, I would be glad to put together a quick, no-obligation quote for ' + name + '.';
} else if (n === 2) {
  middle = 'Following up once more in case the timing was not right before.\n\nA few things clients tell us they value: we clean after hours so your day is never interrupted, we are fully insured, and we are a local Adelaide team with no lock-in contracts.\n\nWould a 10-minute walkthrough some time this week be worth it? The quote is free either way.';
} else {
  middle = 'Last note from us - I do not want to clutter your inbox.\n\nIf cleaning support is not on the agenda right now, no worries at all; the door stays open. If it becomes useful down the track, just reply to this email and I will sort you out quickly.';
}
const fallback_body = greeting + '\n\n' + middle + '\n\n' + signature;
const subject = 'Re: ' + String(r.orig_subject || 'Cleaning support for ' + name);
return { json: {
  candidate_id: r.candidate_id,
  email: r.email,
  subject,
  followup_no: n,
  fallback_body,
  request: {
    business: { name: name, location: r.suburb || null },
    sender: { name: 'Michelle', company: COMPANY },
    original_email: String(r.orig_body || r.orig_subject || 'first outreach email').slice(0, 4000),
    sequence_number: n,
    days_since_last_contact: Math.max(0, Number(r.days_since) || 0)
  }
} };

const prep = $('Prepare Follow-up Request').item.json;
const res = $json;
const ok = res && res.success === true && res.data && typeof res.data.email_body === 'string' && res.data.email_body.trim().length >= 40;
const body = ok ? res.data.email_body.trim() : prep.fallback_body;
return { json: {
  candidate_id: prep.candidate_id,
  email: prep.email,
  subject: prep.subject,
  body,
  followup_no: prep.followup_no,
  method: ok ? 'ai_generate_followup_v2' : 'template_fallback_v1'
} };
